*{box-sizing:border-box} :root{--ink:#f4f1ea;--muted:#92979e;--red:#f35c4a;--cyan:#51d5d0;--panel:rgba(15,19,24,.82)}html,body{height:100%;margin:0;background:#10141a;color:var(--ink);font-family:'DM Sans',sans-serif;overflow:hidden;touch-action:none}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;height:100dvh;overflow:hidden;background:radial-gradient(ellipse at 50% 45%,#202932,#11161c 62%,#0d1116)}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,11,15,.53),transparent 25%,transparent 72%,rgba(8,11,15,.58)),radial-gradient(ellipse at center,transparent 35%,rgba(5,8,11,.42) 100%)}.topbar{position:absolute;z-index:2;top:max(18px,env(safe-area-inset-top));left:4.2%;right:4.2%;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:1.1px}.brand b{color:var(--red)}.brand small{display:block;color:#9da1a7;font:600 8px 'DM Sans',sans-serif;letter-spacing:2px;margin-top:1px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(243,92,74,.68);color:var(--red);font:800 13px 'Barlow Condensed';transform:skew(-8deg)}.round-pill{border:1px solid rgba(255,255,255,.14);background:rgba(15,19,24,.55);padding:9px 14px;border-radius:4px;font:700 9px 'DM Sans';letter-spacing:1.4px;color:#c5c6c6}.round-pill i,.eyebrow span{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--red);box-shadow:0 0 11px var(--red);margin-right:7px}.round-pill>span{padding:0 6px;color:#656c72}.round-pill b{color:#fff}.sound{border:0;background:transparent;color:#aaa;letter-spacing:1.3px;font-size:13px;cursor:pointer}.sound span{font-size:8px}.hud{position:absolute;z-index:2;top:15.5%;left:5%;right:5%;display:grid;grid-template-columns:minmax(150px,1fr) 70px minmax(150px,1fr);align-items:center;gap:12px}.fighter-card{padding:10px 12px;background:linear-gradient(90deg,rgba(12,16,20,.75),rgba(12,16,20,.3));border-left:2px solid var(--cyan)}.enemy-card{border-left:0;border-right:2px solid var(--red);text-align:right;background:linear-gradient(270deg,rgba(12,16,20,.75),rgba(12,16,20,.3))}.fighter-name{font:800 15px 'Barlow Condensed';letter-spacing:1px}.fighter-name>span{font-size:10px;color:var(--cyan);margin-right:5px}.enemy-card .fighter-name>span{color:var(--red)}.fighter-name small{font:600 8px 'DM Sans';letter-spacing:1.3px;color:#848c92;margin-left:8px}.health-track{height:5px;background:rgba(255,255,255,.12);margin-top:7px;overflow:hidden}.health-fill{height:100%;transition:width .25s ease}.player-fill{background:linear-gradient(90deg,#35a9a7,#62e1ce);box-shadow:0 0 10px #35a9a755}.enemy-fill{background:linear-gradient(90deg,#fd785e,#dc3e46);float:right;box-shadow:0 0 10px #dc3e4655}.health-meta{display:flex;justify-content:space-between;margin-top:5px;color:#899097;font-size:7px;letter-spacing:1px}.enemy-card .health-meta{flex-direction:row-reverse}.health-meta b{color:#e5e6e3;font-size:9px}.versus{text-align:center;color:#ffffff55;font:900 20px 'Barlow Condensed';font-style:italic}.weapon-panel{position:absolute;z-index:2;top:39%;left:4.2%;width:174px}.weapon-label{display:block;font:700 8px 'DM Sans';letter-spacing:2px;color:#a6abb0;margin:0 0 7px 3px}.weapon-list{display:grid;gap:5px}.weapon{display:flex;align-items:center;text-align:left;gap:10px;width:100%;padding:8px 9px;background:rgba(12,16,20,.62);border:1px solid rgba(255,255,255,.11);border-radius:3px;cursor:pointer;transition:.15s}.weapon.active{border-color:rgba(243,92,74,.8);background:rgba(56,29,30,.78);box-shadow:inset 2px 0 var(--red)}.weapon-icon{font:900 21px 'Barlow Condensed';color:#ddd;width:22px;text-align:center;transform:rotate(-25deg)}.bat-icon{font-size:24px;color:#d4a875}.board-icon{font-size:16px;color:#9bc0bb;transform:none}.weapon b,.weapon small{display:block}.weapon b{font:800 11px 'Barlow Condensed';letter-spacing:1px}.weapon small{font-size:7px;color:#92999e;letter-spacing:1px;margin-top:2px}.weapon kbd{margin-left:auto;color:#828a90;font-size:9px;background:#ffffff0b;padding:2px 5px;border-radius:2px}.status-message{position:absolute;z-index:2;top:49%;left:50%;transform:translate(-50%,-50%);white-space:nowrap;font:700 9px 'DM Sans';letter-spacing:2px;color:rgba(245,242,235,.73);text-shadow:0 1px 5px #000}.controls-hint{position:absolute;z-index:2;bottom:22px;left:50%;transform:translateX(-50%);font-size:8px;color:#a0a4a8;letter-spacing:1.3px;white-space:nowrap}.controls-hint span{color:#e9e9e5;font:700 9px 'Barlow Condensed';border:1px solid #ffffff35;border-radius:2px;padding:3px 5px}.controls-hint i{font-style:normal;color:var(--red);padding:0 8px}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;padding:24px;background:rgba(7,10,14,.45);backdrop-filter:blur(3px);transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.intro-card{width:min(440px,92vw);padding:36px 39px;background:linear-gradient(135deg,rgba(21,27,33,.96),rgba(14,18,23,.94));border:1px solid rgba(255,255,255,.13);box-shadow:0 25px 90px #0009;position:relative}.intro-card:before{content:'';position:absolute;top:-1px;left:30px;width:62px;height:2px;background:var(--red)}.eyebrow{font:700 9px 'DM Sans';letter-spacing:2px;color:#b1b5b8}.intro-card h1{font:900 clamp(42px,8vw,60px)/.86 'Barlow Condensed';letter-spacing:1px;margin:22px 0 14px}.intro-card h1 em{font-style:normal;color:var(--red)}.intro-card p{color:#afb4b7;font-size:12px;line-height:1.65;max-width:330px;margin:0 0 22px}.intro-weapons{display:flex;gap:20px;padding:13px 0 18px;border-top:1px solid #ffffff15;margin-bottom:4px}.intro-weapons span{font-size:8px;color:#f36958;letter-spacing:1px}.intro-weapons b,.intro-weapons small{display:block}.intro-weapons b{color:#ecece8;font:800 12px 'Barlow Condensed';margin:4px 0 2px}.intro-weapons small{color:#858c91;font-size:8px;letter-spacing:0}.primary-btn{width:100%;display:flex;justify-content:space-between;align-items:center;padding:14px 16px;background:var(--red);border:0;border-radius:2px;color:#fff;font:800 12px 'Barlow Condensed';letter-spacing:1.7px;cursor:pointer;box-shadow:0 7px 24px #f35c4a35;transition:transform .15s,background .15s}.primary-btn:hover{transform:translateY(-2px);background:#ff705d}.primary-btn span{font-size:20px}.disclaimer{text-align:center;font-size:7px;letter-spacing:1px;color:#717a80;margin-top:13px}.score-line{display:flex;gap:9px;align-items:center;border-top:1px solid #ffffff16;padding:15px 0;margin-bottom:7px;font:700 8px 'DM Sans';letter-spacing:1px;color:#92999e}.score-line b{color:#fff;font-size:13px;margin-right:auto}.mobile-controls{display:none;position:absolute;inset:auto 0 max(22px,env(safe-area-inset-bottom)) 0;z-index:3;align-items:end;justify-content:space-between;padding:0 5%;pointer-events:none}.stick-zone{pointer-events:auto;display:flex;flex-direction:column;align-items:center;gap:6px;font-size:7px;letter-spacing:1.4px;color:#aab0b3}.stick-base{width:104px;height:104px;border-radius:50%;background:rgba(11,16,21,.48);border:1px solid #ffffff28;display:grid;place-items:center;box-shadow:inset 0 0 20px #0007}.stick-knob{width:46px;height:46px;border-radius:50%;background:linear-gradient(145deg,#404950,#252d33);border:1px solid #ffffff40;box-shadow:0 4px 12px #0009;transform:translate(0,0)}.mobile-actions{display:flex;align-items:end;gap:12px;pointer-events:auto}.touch-action{border:1px solid #ffffff38;background:#171d22dd;box-shadow:0 6px 20px #0008;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer}.dodge-btn{width:57px;height:57px;border-radius:50%;font-size:22px;color:#ddd}.touch-action small{font:700 7px 'DM Sans';letter-spacing:1px;color:#a8afb4}.attack-btn{width:78px;height:78px;border-radius:50%;background:linear-gradient(145deg,#f36c55,#bd3d3c);border-color:#ff9a76;font:900 14px 'Barlow Condensed';letter-spacing:1px;box-shadow:0 5px 25px #e94d3b55}.attack-btn small{color:#ffe0d9}.toast{position:absolute;z-index:4;top:27%;left:50%;transform:translate(-50%,-10px);background:#111a;border:1px solid #ffffff22;padding:9px 15px;font:700 10px 'DM Sans';letter-spacing:1px;color:#fff;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}#game.hit-flash:after{content:'';position:absolute;inset:0;background:rgba(255,65,57,.16);pointer-events:none;animation:flash .2s ease-out}@keyframes flash{from{opacity:1}to{opacity:0}}
@media(max-width:700px){.topbar{top:max(12px,env(safe-area-inset-top));left:4%;right:4%}.brand{font-size:14px}.brand-mark{width:30px;height:30px}.round-pill{font-size:7px;padding:8px 9px;letter-spacing:.8px}.round-pill>span{padding:0 3px}.sound{font-size:11px}.sound span{display:none}.hud{top:12%;left:4%;right:4%;grid-template-columns:1fr 30px 1fr;gap:4px}.fighter-card{padding:7px 7px}.fighter-name{font-size:12px}.fighter-name small{font-size:6px;margin-left:3px;letter-spacing:.5px}.health-track{height:4px;margin-top:5px}.health-meta{font-size:6px}.versus{font-size:15px}.weapon-panel{top:auto;bottom:calc(max(142px, 17vh) + env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);width:auto}.weapon-label{display:none}.weapon-list{display:flex;gap:5px}.weapon{width:90px;padding:7px 5px;gap:5px;justify-content:center}.weapon-icon{font-size:17px;width:15px}.weapon b{font-size:9px}.weapon small{font-size:6px}.weapon kbd{display:none}.status-message{top:50%;font-size:8px;letter-spacing:1px}.controls-hint{display:none}.mobile-controls{display:flex}.intro-card{padding:29px 25px}.intro-card h1{font-size:48px}.intro-card p{font-size:11px}.intro-weapons{gap:15px}.end-card h1{font-size:54px}}
@media(min-width:701px) and (max-height:650px){.hud{top:14%}.weapon-panel{top:35%}.intro-card{padding:26px 34px}.intro-card h1{margin-top:14px}.intro-card p{margin-bottom:14px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#161d24');
scene.fog = new THREE.FogExp2('#161d24', .035);
const camera = new THREE.PerspectiveCamera(42, innerWidth/innerHeight, .1, 100);
camera.position.set(0, 7.3, 12.8);
camera.lookAt(0, .6, 0);
const clock = new THREE.Clock();
const mat = (color, roughness=.8, metalness=0, extra={})=>new THREE.MeshStandardMaterial({color, roughness, metalness, ...extra});
const mats={floor:mat('#30383a'), concrete:mat('#343c40'), dark:mat('#20272b'), metal:mat('#465157',.48,.65), red:mat('#f35c4a',.36,.1,{emissive:'#5c1714',emissiveIntensity:.7}), cyan:mat('#54d6ce',.35,.1,{emissive:'#164b4a',emissiveIntensity:.65}), amber:mat('#f3b35f',.42,.15,{emissive:'#5a3215',emissiveIntensity:.4}), white:mat('#bfc6c4'), black:mat('#171b1e'), skin:mat('#bd8669'), enemySkin:mat('#a96f5c'), playerJacket:mat('#387b78'), enemyJacket:mat('#873d42'), denim:mat('#283940'), pants:mat('#303237'), shoe:mat('#171a1c'), wood:mat('#8b6241'), blood:mat('#bd3837',.5,0,{emissive:'#501716',emissiveIntensity:.3})};
scene.add(new THREE.HemisphereLight('#a9c8d1','#202127',2.05));
const keyLight=new THREE.DirectionalLight('#ffe3bf',3.1);keyLight.position.set(-4,9,5);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-10;keyLight.shadow.camera.right=10;keyLight.shadow.camera.top=10;keyLight.shadow.camera.bottom=-10;scene.add(keyLight);
const redLight=new THREE.PointLight('#f05545',14,10,2);redLight.position.set(-5,3,-2);scene.add(redLight);
const blueLight=new THREE.PointLight('#3babc4',15,11,2);blueLight.position.set(5,3,-3);scene.add(blueLight);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(90,90),mats.floor);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
// Scuffed concrete fighting square and perimeter markings
const arena=new THREE.Mesh(new THREE.PlaneGeometry(13,10),mat('#3b4141'));arena.rotation.x=-Math.PI/2;arena.position.y=.006;arena.receiveShadow=true;scene.add(arena);
const grid=new THREE.GridHelper(13,26,'#62645e','#4c5251');grid.position.y=.014;grid.material.transparent=true;grid.material.opacity=.2;scene.add(grid);
function box(parent, name, size, position, material, rotation){const m=new THREE.Mesh(new THREE.BoxGeometry(...size),material);m.name=name;m.position.set(...position);if(rotation)m.rotation.set(...rotation);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
// Urban alley perimeter, lit windows and graffiti-like neon details
for(let i=0;i<8;i++){
 const side=i<4?-1:1, j=i%4, x=side*(8.1+j*.35), z=-5.5+j*3.1;
 const h=5.8+(j%2)*2.1;box(scene,'alley building',[2.4,h,2.7],[x,h/2-0.1,z],mat(j%2?'#252d33':'#20282e'));
 for(let w=0;w<3;w++){const win=box(scene,'window',[.04,.55,.72],[x-side*1.22,1.3+w*1.2,z-.45],mat(w%2?'#d18b4e':'#437580',.4,0,{emissive:w%2?'#713d1e':'#153b47',emissiveIntensity:.45}));}
}
for(let x of [-6.4,6.4]){
 box(scene,'arena wall',[.25,1.25,10],[x,.58,0],mats.dark);
 for(let z=-4;z<=4;z+=2)box(scene,'wall reflector',[.04,.08,.08],[x*1.005,1.04,z],x<0?mats.red:mats.cyan);
}
// Set dressing: dumpsters, stacked crates, bollards, puddles
for(const [x,z] of [[-5,-2],[5,2]]){
 box(scene,'dumpster',[1.25,.78,.9],[x,.4,z],mat('#26383a'));box(scene,'dumpster lid',[1.32,.1,.95],[x,.82,z],mat('#384548'),[.03,0,0]);
 for(let dx of [-.42,.42]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.13,.13,.1,12),mats.black);wheel.rotation.z=Math.PI/2;wheel.position.set(x+dx,.16,z+.35);scene.add(wheel);}
}
for(const [x,z] of [[-4,2.5],[4,-2.5],[-5,4],[5,-4]]){
 box(scene,'crate',[.72,.72,.72],[x,.37,z],mats.wood);box(scene,'crate slat',[.77,.09,.75],[x,.32,z],mat('#62462f'));
}
const puddleMat=new THREE.MeshStandardMaterial({color:'#394d50',roughness:.2,metalness:.45,transparent:true,opacity:.65});
for(const [x,z,s] of [[-3.5,-2,.7],[3.3,2.5,.9],[-1,3,.6],[2,-3,.75]]){const p=new THREE.Mesh(new THREE.CircleGeometry(s,32),puddleMat);p.rotation.x=-Math.PI/2;p.position.set(x,.023,z);p.scale.y=.48;scene.add(p);}
// Wall lights and a glowing arena sign
function neonSign(text,color,x,z){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');ctx.clearRect(0,0,512,128);ctx.font='900 72px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor=color;ctx.shadowBlur=22;ctx.fillStyle=color;ctx.fillText(text,256,66);const texture=new THREE.CanvasTexture(c);const sign=new THREE.Mesh(new THREE.PlaneGeometry(4.4,1.1),new THREE.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false}));sign.position.set(x,4.35,z);sign.rotation.y=x<0?.3:-.3;scene.add(sign);}
neonSign('NO RULES','#f35c4a',-5.8,-4.95);neonSign('NIGHT SHIFT','#53c8cf',5.8,-4.9);
for(const x of [-5.8,5.8]){const lamp=new THREE.PointLight(x<0?'#f15b49':'#45c8d1',18,8,2);lamp.position.set(x,4.1,-3.9);scene.add(lamp);}

input.newString:
for(const x of [-5.8,5.8]){const lamp=new THREE.PointLight(x<0?'#f15b49':'#45c8d1',18,8,2);lamp.position.set(x,4.1,-3.9);scene.add(lamp);}
const ring=new THREE.Mesh(new THREE.RingGeometry(3.55,3.62,64),new THREE.MeshBasicMaterial({color:'#b74b40',transparent:true,opacity:.48}));ring.rotation.x=-Math.PI/2;ring.position.y=.025;scene.add(ring);
// Fighters are built from low-poly parts so they remain crisp on phones.
const weaponMeshes={};
function makeWeapon(type){
 const g=new THREE.Group();
 if(type==='knife'){
  const grip=new THREE.Mesh(new THREE.CylinderGeometry(.045,.05,.28,8),mat('#272b2c'));grip.position.y=-.04;g.add(grip);
  const guard=new THREE.Mesh(new THREE.BoxGeometry(.2,.045,.08),mats.metal);guard.position.y=.12;g.add(guard);
  const blade=new THREE.Mesh(new THREE.ConeGeometry(.075,.38,4),mat('#c7d0cf',.22,.8,{metalness:.8}));blade.rotation.z=Math.PI;blade.position.y=.34;g.add(blade);
 }else if(type==='bat'){
  const shaft=new THREE.Mesh(new THREE.CylinderGeometry(.045,.07,.82,10),mats.wood);shaft.position.y=.05;g.add(shaft);
  const knob=new THREE.Mesh(new THREE.CylinderGeometry(.08,.075,.1,10),mat('#332b26'));knob.position.y=-.4;g.add(knob);
  const grip=new THREE.Mesh(new THREE.CylinderGeometry(.047,.047,.22,10),mat('#262729'));grip.position.y=-.25;g.add(grip);
 }else{
  const plank=new THREE.Mesh(new THREE.BoxGeometry(.21,.88,.105),mat('#8d6849'));plank.position.y=.02;g.add(plank);
  for(const y of [-.26,.27]){const nail=new THREE.Mesh(new THREE.CylinderGeometry(.018,.018,.02,6),mats.metal);nail.rotation.x=Math.PI/2;nail.position.set(.03,y,.056);g.add(nail);}
 }
 g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});return g;
}
for(const type of ['knife','bat','board'])weaponMeshes[type]=makeWeapon(type);
function limb(parent, material, length, radius, y){const mesh=new THREE.Mesh(new THREE.CylinderGeometry(radius*.82,radius,length,9),material);mesh.position.y=y;mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);const joint=new THREE.Mesh(new THREE.SphereGeometry(radius,9,7),material);joint.position.y=y-length/2;parent.add(joint);return mesh;}
function makeFighter(isPlayer){
 const root=new THREE.Group();scene.add(root);
 const cloth=isPlayer?mats.playerJacket:mats.enemyJacket, skin=isPlayer?mats.skin:mats.enemySkin;
 const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.34,.48,4,8),cloth);torso.position.y=1.08;torso.castShadow=true;root.add(torso);
 const chest=new THREE.Mesh(new THREE.BoxGeometry(.62,.12,.43),isPlayer?mat('#2a5b5c'):mat('#6a3037'));chest.position.set(0,1.15,.025);chest.castShadow=true;root.add(chest);
 const belt=new THREE.Mesh(new THREE.CylinderGeometry(.25,.28,.13,10),mats.dark);belt.position.y=.73;root.add(belt);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.235,12,10),skin);head.position.y=1.68;head.castShadow=true;root.add(head);
 const hair=new THREE.Mesh(new THREE.SphereGeometry(.24,10,7,0,Math.PI*2,0,Math.PI*.52),isPlayer?mat('#242326'):mat('#221e20'));hair.position.y=1.75;root.add(hair);
 const face=new THREE.Mesh(new THREE.BoxGeometry(.2,.065,.028),mat('#262629'));face.position.set(0,1.63,-.212);root.add(face);
 // jacket collar and shoulder pads
 for(const side of [-1,1]){const pad=new THREE.Mesh(new THREE.SphereGeometry(.19,9,7),isPlayer?mat('#326967'):mat('#77393e'));pad.scale.set(1,.75,1);pad.position.set(side*.37,1.36,0);root.add(pad);}
 const arms=[];
 for(const side of [-1,1]){
  const arm=new THREE.Group();arm.position.set(side*.39,1.32,0);root.add(arm);
  limb(arm,cloth,.38,.115,-.21);
  const fore=new THREE.Group();fore.position.set(0,-.39,0);arm.add(fore);limb(fore,cloth,.36,.09,-.18);
  const glove=new THREE.Mesh(new THREE.SphereGeometry(.105,9,7),mat(isPlayer?'#1f2729':'#252326'));glove.position.set(0,-.4,-.01);fore.add(glove);
  if(side===1){const hand=new THREE.Group();hand.position.set(0,-.43,-.035);fore.add(hand);for(const type of Object.keys(weaponMeshes)){const item=weaponMeshes[type].clone(true);item.visible=false;hand.add(item);}arm.userData.hand=hand;}
  arms.push(arm);
 }
 const legs=[];
 for(const side of [-1,1]){
  const leg=new THREE.Group();leg.position.set(side*.17,.7,0);root.add(leg);
  limb(leg,isPlayer?mats.denim:mats.pants,.45,.135,-.23);
  const shin=new THREE.Group();shin.position.set(0,-.45,0);leg.add(shin);limb(shin,isPlayer?mats.denim:mats.pants,.35,.105,-.18);
  const shoe=new THREE.Mesh(new THREE.BoxGeometry(.22,.13,.34),mats.shoe);shoe.position.set(0,-.4,-.065);shoe.castShadow=true;shin.add(shoe);
  legs.push(leg);
 }
 // Face forward means local negative Z. Add a subtle scarf stripe on the rival.
 if(!isPlayer){const band=new THREE.Mesh(new THREE.BoxGeometry(.42,.07,.05),mats.red);band.position.set(0,1.87,0);root.add(band);}
 return {root,arms,legs,health:100,maxHealth:100,attackTimer:0,attackAnim:0,hitFlash:0,stun:0,dodge:0,walk:0,weapon:'knife',isPlayer,dead:false};
}
const player=makeFighter(true), enemy=makeFighter(false);
player.root.position.set(-2.2,0,1.0);enemy.root.position.set(2.2,0,-.7);
